/* Curated, week-matched teaching and practice materials. All datasets synthetic. */
window.DALP_WEEK_MEDIA = {"introduction":[{"week":1,"dataset":"kiosk_week.csv","datasetLabel":"Kiosk Week (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=70s","videoTitle":"Week 1 · Video walkthrough","why":"Before drawing a chart, write a decision statement and identify what a good answer would enable someone to do.","workthrough":"In the kiosk data, distinguish an observable revenue change from a hypothesis about staffing or pricing.","evidence":"Hand in a one-sentence question, its measure, timeframe and two alternative explanations.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/introduction-week-01.md"},{"week":2,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=17311s","videoTitle":"Week 2 · Video walkthrough","why":"Identifiers such as customer_id are categories, even when they look numeric; money and counts require different checks.","workthrough":"Import the sales CSV and classify columns as dates, amounts, labels or keys. Test leading zeros in identifiers.","evidence":"Explain why adding customer IDs produces a meaningless total, then document the correct measure type.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/introduction-week-02.md"},{"week":3,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=2823s","videoTitle":"Week 3 · Video walkthrough","why":"The meaning of one row determines what can be counted. An order-line file differs from one-row-per-customer data.","workthrough":"Inspect the sales export and locate order_id and customer_id. Compare COUNT rows with unique order IDs.","evidence":"Write a grain statement and show a sample duplicate-key test appropriate to that grain.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/introduction-week-03.md"},{"week":4,"dataset":"learning_sales_quality_lab.csv","datasetLabel":"Learning Sales Quality Lab (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=12881s","videoTitle":"Week 4 · Video walkthrough","why":"Quality assurance should precede aggregates: missing revenue and duplicate order IDs can bias a regional KPI.","workthrough":"Use the intentionally dirty file and create an issue register: field, invalid value, proposed rule, owner and resolution.","evidence":"Report how many observations require investigation and which records you would quarantine, not silently remove.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/introduction-week-04.md"},{"week":5,"dataset":"learning_statistics_sample.csv","datasetLabel":"Learning Statistics Sample (CSV)","video":"https://www.youtube.com/watch?v=SzZ6GpcfoQY","videoTitle":"Week 5 · Video walkthrough","why":"The average alone can conceal an extreme delivery wait. The median and spread describe different aspects of performance.","workthrough":"Sort delivery_minutes and calculate mean, median, range and maximum. Compare the averages before and after investigating the outlier.","evidence":"Recommend the statistic a service manager should use and justify it in ordinary language.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/introduction-week-05.md"},{"week":6,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=21589s","videoTitle":"Week 6 · Video walkthrough","why":"A time series reveals movement, while a category comparison reveals ranking; neither chart explains causation by itself.","workthrough":"Plot monthly net sales as a line and regions as a horizontal bar; label units and disclose aggregation.","evidence":"Write one evidenced observation and one limitation for each visual.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/introduction-week-06.md"},{"week":7,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=WH937Gc_8eg&t=2770s","videoTitle":"Week 7 · Video walkthrough","why":"Every business percentage needs a named numerator, denominator and cohort. Revenue and profit must use the same filters.","workthrough":"With monthly KPI data, compute sales attainment = net_sales_ngn / sales_target_ngn. Compare regions without summing percentages.","evidence":"Reconcile the total attainment from summed sales and targets, then state the strongest underperformance.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/introduction-week-07.md"},{"week":8,"dataset":"learning_staff_operations.csv","datasetLabel":"Learning Staff Operations (CSV)","video":"https://www.youtube.com/watch?v=TImRJTzphhE","videoTitle":"Week 8 · Video walkthrough","why":"Anonymization and access control solve different problems. Minimise what is collected and exposed at every stage.","workthrough":"Use synthetic staff operations. Publish department totals but do not expose row-level worker IDs in the presentation.","evidence":"Create a report sharing checklist covering roles, retention, purpose, and suppression of small groups.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/introduction-week-08.md"},{"week":9,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=29175s","videoTitle":"Week 9 · Video walkthrough","why":"A persuasive insight has context, quantified evidence, caveat and next action. “The West declined” without a period is incomplete.","workthrough":"Compare two months of regional sales, identify the largest absolute variance and suggest a follow-up query.","evidence":"Create a 90-word insight with one recommendation and one statement of what the data does not establish.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/introduction-week-09.md"},{"week":10,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=23562s","videoTitle":"Week 10 · Video walkthrough","why":"A complete analysis needs a reproducible source, a computation, a quality check, a chart and a recommendation.","workthrough":"Combine sales and monthly targets into a two-chart executive summary. Match month and region before comparing.","evidence":"Submit a mini-report with question, data checks, KPI definition, findings, limitations and action.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/introduction-week-10.md"}],"excel":[{"week":1,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=zXnQNytHCPM","videoTitle":"Week 1 · Video walkthrough","why":"Learn the Ribbon, Formula Bar, Name Box, worksheet tabs and Table tools; the display format does not replace a stored data type.","workthrough":"Open the sales CSV, apply Date and Currency formats, and test =ISNUMBER() on a true date or amount.","evidence":"Identify one text-as-number trap and show how to correct it without losing the original.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/excel-week-01.md"},{"week":2,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=16081s","videoTitle":"Week 2 · Video walkthrough","why":"A structured Excel Table auto-expands and provides named columns, which keeps formulas readable when data grows.","workthrough":"Select the sales range, press Ctrl+T, verify headers, name the table Sales, and try =SUM(Sales[quantity]).","evidence":"Add one test row and explain why a structured SUM includes it automatically.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/excel-week-02.md"},{"week":3,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=17175s","videoTitle":"Week 3 · Video walkthrough","why":"Relative references move when copied; absolute references preserve assumptions such as a tax or commission rate.","workthrough":"Create a small scenario sheet with unit price and quantity, put a rate in $F$1 and copy =B2*C2*(1+$F$1).","evidence":"Check three rows against a hand-calculated result and note what changes when a $ is omitted.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/excel-week-03.md"},{"week":4,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=17175s","videoTitle":"Week 4 · Video walkthrough","why":"SUMIFS and COUNTIFS answer conditional business questions when every criteria range has matching dimensions.","workthrough":"Use completed rows in the sales CSV. Calculate regional revenue with SUMIFS on a calculated line-revenue column.","evidence":"Compare two region totals with a PivotTable and disclose that cancelled orders were excluded.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/excel-week-04.md"},{"week":5,"dataset":"learning_product_catalog.csv","datasetLabel":"Learning Product Catalog (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=19207s","videoTitle":"Week 5 · Video walkthrough","why":"A lookup requires a stable key: do not join merely on a product name if labels are duplicated or inconsistent.","workthrough":"Use the product catalog independently and practise exact-match XLOOKUP by SKU; return “Not found” for a missing code.","evidence":"Audit the number of missing matches, then explain why category is not a reliable SKU-level key.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/excel-week-05.md"},{"week":6,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=zXnQNytHCPM","videoTitle":"Week 6 · Video walkthrough","why":"Dynamic arrays recalculate output as source rows change; spill blocks and Excel version compatibility require attention.","workthrough":"From sales data, use UNIQUE and SORT for region lists, then FILTER completed orders from a selected region.","evidence":"Show which cell holds the formula, where the results spill and what causes #SPILL!.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/excel-week-06.md"},{"week":7,"dataset":"learning_sales_quality_lab.csv","datasetLabel":"Learning Sales Quality Lab (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=22498s","videoTitle":"Week 7 · Video walkthrough","why":"Clean operations must be reversible and measurable; trimming a region label and deleting duplicated business records are not equivalent.","workthrough":"Import the dirty sales file, inspect blank price, malformed quantity and duplicated order ID, and make a corrected copy.","evidence":"Write a before/after quality summary and keep every disputed row in an exceptions tab.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/excel-week-07.md"},{"week":8,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=lH7HfwUFnYA","videoTitle":"Week 8 · Video walkthrough","why":"PivotTables aggregate without altering raw data, but incorrect Value settings can silently convert sums into counts.","workthrough":"With the clean sales file, create a completed-sales PivotTable by region and month; add a slicer for category.","evidence":"Reconcile the PivotTable total to an independently calculated source sum and test a slicer selection.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/excel-week-08.md"},{"week":9,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=21589s","videoTitle":"Week 9 · Video walkthrough","why":"The dashboard should answer 2–3 stakeholder questions instantly: what happened, where, and what needs attention.","workthrough":"Use monthly KPI data for revenue, target and margin cards; add a trend chart and region comparison with clear labels.","evidence":"Create a short presenter script with headline, evidence, caveat and action.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/excel-week-09.md"},{"week":10,"dataset":"learning_sales_quality_lab.csv","datasetLabel":"Learning Sales Quality Lab (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=23762s","videoTitle":"Week 10 · Video walkthrough","why":"Power Query is preferable to manual cleanup for recurring files because applied steps can be reviewed and refreshed.","workthrough":"Use Data > Get Data > From Text/CSV to import the dirty sales file, fix types and record exceptions.","evidence":"Refresh from an unchanged source and show which transformation steps are reproducible.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/excel-week-10.md"}],"sql":[{"week":1,"dataset":"retail_practice.sqlite","datasetLabel":"Retail Practice (SQLite)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=908s","videoTitle":"Week 1 · Video walkthrough","why":"Begin in the query editor and inspect table schema. Primary keys identify rows; foreign keys express valid relationships.","workthrough":"Open retail_practice.sqlite and compare orders and customers; identify order_id and customer_id.","evidence":"Document row grain and expected cardinality before writing any JOIN.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/sql-week-01.md"},{"week":2,"dataset":"retail_practice.sqlite","datasetLabel":"Retail Practice (SQLite)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=1484s","videoTitle":"Week 2 · Video walkthrough","why":"SELECT decides columns, FROM decides sources, WHERE removes rows and ORDER BY sorts results.","workthrough":"In orders, return order_id, region and order_date for a single region; use LIMIT for a readable preview.","evidence":"Explain why filtering before aggregation changes the population but ordering does not.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/sql-week-02.md"},{"week":3,"dataset":"retail_practice.sqlite","datasetLabel":"Retail Practice (SQLite)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=2334s","videoTitle":"Week 3 · Video walkthrough","why":"Aggregate only at the grouping grain: COUNT(*) counts rows while COUNT(DISTINCT customer_id) counts customers.","workthrough":"Group completed orders by region and compare COUNT(*), SUM(quantity) and SUM(quantity*unit_price).","evidence":"Validate one group independently and clarify inclusion of returns or cancellations.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/sql-week-03.md"},{"week":4,"dataset":"retail_practice.sqlite","datasetLabel":"Retail Practice (SQLite)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=2823s","videoTitle":"Week 4 · Video walkthrough","why":"Joining a one-to-many table can multiply records. Test distinct keys and row counts before and after the join.","workthrough":"Join orders to customers on customer_id, then compare the overall order count and revenue with the unjoined table.","evidence":"Describe a fanout diagnostic and how you would prevent an unintended metric increase.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/sql-week-04.md"},{"week":5,"dataset":"retail_practice.sqlite","datasetLabel":"Retail Practice (SQLite)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=4111s","videoTitle":"Week 5 · Video walkthrough","why":"NULL means unknown or missing, not automatically zero. CASE introduces documented classification rules.","workthrough":"Write a CASE expression for an order value band and use COALESCE only where the business rule permits a default.","evidence":"Count unclassified rows and explain how a NULL differs from the numeric value 0.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/sql-week-05.md"},{"week":6,"dataset":"retail_practice.sqlite","datasetLabel":"Retail Practice (SQLite)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=5642s","videoTitle":"Week 6 · Video walkthrough","why":"CTEs separate stages and make validation easier, but their names should communicate intent rather than conceal logic.","workthrough":"Create a cleaned_orders CTE and a by_region CTE, then select the final summary from the second one.","evidence":"Compare intermediate row counts and ensure no premature aggregation masks detail.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/sql-week-06.md"},{"week":7,"dataset":"retail_practice.sqlite","datasetLabel":"Retail Practice (SQLite)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=5402s","videoTitle":"Week 7 · Video walkthrough","why":"Window functions preserve rows while adding rank, running totals and period comparisons.","workthrough":"Use ROW_NUMBER() OVER (PARTITION BY region ORDER BY order_date) and a regional running revenue total.","evidence":"Explain why GROUP BY and window output have different row counts.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/sql-week-07.md"},{"week":8,"dataset":"retail_practice.sqlite","datasetLabel":"Retail Practice (SQLite)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=8217s","videoTitle":"Week 8 · Video walkthrough","why":"A cohort groups records by the business event that defines membership—not simply by whichever date is convenient.","workthrough":"Group customers by signup month; compare with orders grouped by order month and explain the different populations.","evidence":"Write an unambiguous cohort definition and note which timezone and calendar rules it needs.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/sql-week-08.md"},{"week":9,"dataset":"retail_practice.sqlite","datasetLabel":"Retail Practice (SQLite)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=7795s","videoTitle":"Week 9 · Video walkthrough","why":"Performance improves by limiting scanned data and selecting the right columns. Inspect plans before guessing.","workthrough":"Use EXPLAIN QUERY PLAN on a filtered orders query; compare narrow projection against SELECT * and identify indexed keys.","evidence":"Record the query, estimated approach and result validation, without claiming a speedup from tiny training data.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/sql-week-09.md"},{"week":10,"dataset":"retail_practice.sqlite","datasetLabel":"Retail Practice (SQLite)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=8209s","videoTitle":"Week 10 · Video walkthrough","why":"A report dataset should have a documented grain, stable metric definition, consistent filters and reproducible checks.","workthrough":"Build a monthly revenue-by-region query and reconcile summed detail totals to the published summary.","evidence":"Export a stakeholder-ready table with definitions and one suggested chart.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/sql-week-10.md"}],"powerbi":[{"week":1,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=31982s","videoTitle":"Week 1 · Video walkthrough","why":"Power BI Desktop has Report, Data and Model views. Define grain before choosing visuals, then import the right sources.","workthrough":"Open Power BI Desktop, Get Data > Text/CSV, inspect the sales data and name fact and dimensions clearly.","evidence":"Write the data grain, a target KPI definition and a report question before designing visuals.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerbi-week-01.md"},{"week":2,"dataset":"learning_sales_quality_lab.csv","datasetLabel":"Learning Sales Quality Lab (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=32751s","videoTitle":"Week 2 · Video walkthrough","why":"Power Query records import transformations, including type changes, errors and locale handling.","workthrough":"Choose Transform Data, inspect Applied Steps and correct deliberate data-quality issues without erasing uncertain rows.","evidence":"Refresh once and compare the exception count before and after your documented rules.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerbi-week-02.md"},{"week":3,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=33537s","videoTitle":"Week 3 · Video walkthrough","why":"A star schema places business events in fact tables and descriptive lookup fields in dimensions.","workthrough":"Create separate Region and Calendar dimensions, relate them one-to-many to the sales fact, and inspect filter direction.","evidence":"Test whether a region slicer filters the fact once, without duplicating transactions.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerbi-week-03.md"},{"week":4,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=34053s","videoTitle":"Week 4 · Video walkthrough","why":"A DAX measure responds to filter context. A calculated column materializes a row-level value during refresh.","workthrough":"Write Total Sales := SUMX(Orders, Orders[quantity]*Orders[unit_price_ngn]) and test by region.","evidence":"Compare a card before and after selecting a region, then explain why the measure changes.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerbi-week-04.md"},{"week":5,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=WH937Gc_8eg&t=2770s","videoTitle":"Week 5 · Video walkthrough","why":"Calculated columns are useful for row attributes; measures are usually preferable for aggregated KPI logic.","workthrough":"Build Completed Sales as a measure applying status=\"Completed\" and compare with a calculated row amount.","evidence":"Record one case where a column would increase model size without helping the required visual.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerbi-week-05.md"},{"week":6,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=WH937Gc_8eg&t=7494s","videoTitle":"Week 6 · Video walkthrough","why":"Time intelligence relies on a marked date table and the calendar logic expected by the business.","workthrough":"Create a Calendar table covering the full period, mark it as a date table and compare current to previous month.","evidence":"Show a missing-month check and explain what happens when time periods are not contiguous.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerbi-week-06.md"},{"week":7,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=WH937Gc_8eg&t=8512s","videoTitle":"Week 7 · Video walkthrough","why":"A ratio should evaluate numerator and denominator under intentionally chosen filters, including ALL or REMOVEFILTERS.","workthrough":"Calculate target attainment using DIVIDE(SUM(Net Sales),SUM(Target)) then test region and month slicers.","evidence":"Show the overall percentage from aggregate totals rather than averaging regional percentages.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerbi-week-07.md"},{"week":8,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=36534s","videoTitle":"Week 8 · Video walkthrough","why":"Visual design is not cosmetic; ordering, consistent units, legibility and target signals shape decisions.","workthrough":"Create a KPI summary, sales trend and region variance bar chart using the monthly KPI data.","evidence":"Write a one-minute explanation: headline, evidence, caveat and action.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerbi-week-08.md"},{"week":9,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=WH937Gc_8eg&t=7310s","videoTitle":"Week 9 · Video walkthrough","why":"Cross-filter, highlight and drill-through determine what happens when a reader interacts with the report.","workthrough":"Use Format > Edit interactions and test how a region chart affects revenue card and time series.","evidence":"Record expected behaviour for each slicer and check totals after resetting filters.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerbi-week-09.md"},{"week":10,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=WH937Gc_8eg&t=10072s","videoTitle":"Week 10 · Video walkthrough","why":"Performance problems can originate in the model, DAX or excessive visuals. Optimisation requires a measured baseline.","workthrough":"Inspect Performance Analyzer, prune unneeded columns and compare measure output before and after.","evidence":"Save a quality checklist: totals, refresh, slicers, labels, performance and sharing permissions.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerbi-week-10.md"}],"tableau":[{"week":1,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=26209s","videoTitle":"Week 1 · Video walkthrough","why":"Tableau separates dimensions and measures and uses shelves such as Rows, Columns, Marks and Filters.","workthrough":"Connect to the sales CSV and drag Region to Rows and a revenue measure to Columns; inspect aggregation.","evidence":"Explain whether each field is discrete or continuous and what one mark represents.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/tableau-week-01.md"},{"week":2,"dataset":"learning_customer_cohorts.csv","datasetLabel":"Learning Customer Cohorts (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=28460s","videoTitle":"Week 2 · Video walkthrough","why":"Incorrect data relationships can duplicate measures, while relationships and joins do not behave identically.","workthrough":"Connect customer cohorts as a separate source, review field types, and sketch intended keys before joining.","evidence":"State why a customer-grain file should not be joined to order-grain data without a clear plan.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/tableau-week-02.md"},{"week":3,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=27620s","videoTitle":"Week 3 · Video walkthrough","why":"Comparisons favour bars; time trends favour lines. Choose a chart after naming the question.","workthrough":"Plot monthly sales as a line and regions as bars using monthly KPI data; add clear titles and number formats.","evidence":"Confirm grand totals and write a one-sentence finding with units.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/tableau-week-03.md"},{"week":4,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=27233s","videoTitle":"Week 4 · Video walkthrough","why":"Calculated fields can be row-level or aggregate; mixing both levels without planning creates errors.","workthrough":"Create an amount expression from quantity and unit price, then aggregate it by category or region.","evidence":"Explain why SUM([Price]) * SUM([Quantity]) is not always the same as SUM([Price]*[Quantity]).","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/tableau-week-04.md"},{"week":5,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=29112s","videoTitle":"Week 5 · Video walkthrough","why":"A filter changes visible data, while a parameter is a value that can drive a calculation or display choice.","workthrough":"Add a date filter and a simple KPI selection parameter for monthly sales versus margin.","evidence":"Test the view after clearing filters and document any misleading empty states.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/tableau-week-05.md"},{"week":6,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=K-3lEMHe2jU","videoTitle":"Week 6 · Video walkthrough","why":"FIXED level-of-detail expressions compute at a declared level independent of marks, subject to filter order.","workthrough":"Build a fixed regional benchmark and compare it to category-level marks. Inspect the filters applied.","evidence":"Describe how context filters can affect a FIXED calculation.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/tableau-week-06.md"},{"week":7,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=3_DeQdE25Bc","videoTitle":"Week 7 · Video walkthrough","why":"Table calculations operate on marks after aggregation and depend on addressing and partitioning choices.","workthrough":"Create a running total over month and percent-of-total by region. Compare table direction settings.","evidence":"Explain what changes when the table calc is computed across versus down.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/tableau-week-07.md"},{"week":8,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=29543s","videoTitle":"Week 8 · Video walkthrough","why":"A good dashboard uses consistent spacing and a deliberate interaction map rather than filling the whole canvas.","workthrough":"Arrange a KPI card, trend and regional bar into a responsive dashboard; add filter actions.","evidence":"Test select/clear behaviour and confirm titles still describe the filtered data.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/tableau-week-08.md"},{"week":9,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=29112s","videoTitle":"Week 9 · Video walkthrough","why":"Storytelling should connect claim, evidence, uncertainty and recommendation in accessible language.","workthrough":"Add short captions, colour-independent labels, descriptive titles and a next-action callout.","evidence":"Produce an executive summary that does not imply the chart proves causation.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/tableau-week-09.md"},{"week":10,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=PSNXoAs2FtQ&t=29327s","videoTitle":"Week 10 · Video walkthrough","why":"A portfolio story should be reproducible: sources, calculated fields, filters and caveats need documentation.","workthrough":"Build a complete retail performance story with at least two linked views and one validated KPI.","evidence":"Save a handover note with definitions, data provenance, limitations and proposed business action.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/tableau-week-10.md"}],"powerquery":[{"week":1,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=VO-MyVMKUC4","videoTitle":"Week 1 · Video walkthrough","why":"The Power Query Editor is a recipe of Applied Steps. The data preview is not the entire dataset.","workthrough":"Load the sales file; inspect column quality, column distribution, header promotion and source-step configuration.","evidence":"Write a repeatable source-to-output recipe and identify what may fail on refresh.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerquery-week-01.md"},{"week":2,"dataset":"learning_sales_quality_lab.csv","datasetLabel":"Learning Sales Quality Lab (CSV)","video":"https://www.youtube.com/watch?v=WH937Gc_8eg&t=1880s","videoTitle":"Week 2 · Video walkthrough","why":"Locale-aware type conversion prevents dates and decimal numbers being silently misinterpreted.","workthrough":"Import the deliberately dirty file and inspect 03/02/2026 as text before applying locale; document the intended date order.","evidence":"Identify rows requiring business confirmation rather than guessing date conventions.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerquery-week-02.md"},{"week":3,"dataset":"learning_sales_quality_lab.csv","datasetLabel":"Learning Sales Quality Lab (CSV)","video":"https://www.youtube.com/watch?v=WH937Gc_8eg&t=1880s","videoTitle":"Week 3 · Video walkthrough","why":"Replace Errors and Remove Errors are different business decisions; cleaning should preserve a trackable exception log.","workthrough":"Count nulls, errors and duplicate order IDs before building a cleaned output and an exceptions query.","evidence":"Show how to trace a removed or corrected record back to the source.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerquery-week-03.md"},{"week":4,"dataset":"learning_sales_quality_lab.csv","datasetLabel":"Learning Sales Quality Lab (CSV)","video":"https://www.youtube.com/watch?v=WH937Gc_8eg&t=1880s","videoTitle":"Week 4 · Video walkthrough","why":"Text normalization helps joins, but over-normalizing can collapse distinct keys.","workthrough":"Apply Trim and Clean to region, use consistent casing, and review mismatched categories.","evidence":"Explain why standardising labels is safe while inventing missing identifiers is not.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerquery-week-04.md"},{"week":5,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=WH937Gc_8eg&t=1880s","videoTitle":"Week 5 · Video walkthrough","why":"Conditional columns should implement documented rules and preserve an else/default state.","workthrough":"Create a revenue band from unit price and a completed-status flag with an explicit unknown category.","evidence":"Count unknown cases separately and test boundary values.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerquery-week-05.md"},{"week":6,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=VO-MyVMKUC4","videoTitle":"Week 6 · Video walkthrough","why":"Append combines rows from compatible tables; columns align by name, so schema drift may introduce blanks.","workthrough":"Split sales by quarter, append back together and compare row totals and column types.","evidence":"Test missing-column behaviour and document your quality checks.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerquery-week-06.md"},{"week":7,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=VO-MyVMKUC4","videoTitle":"Week 7 · Video walkthrough","why":"Merge joins columns by key; unmatched and duplicated matches require diagnostics.","workthrough":"Use a one-column region lookup built from the sales CSV, merge by region and check match counts.","evidence":"Run an anti-join to find missing lookups before loading to the report model.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerquery-week-07.md"},{"week":8,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=VO-MyVMKUC4","videoTitle":"Week 8 · Video walkthrough","why":"Group By summarizes rows; all-rows and detail aggregations answer different questions.","workthrough":"Group completed orders by region and compute total quantity, row count and average unit price.","evidence":"Check that aggregate totals match the ungrouped dataset after the same filter.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerquery-week-08.md"},{"week":9,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=VO-MyVMKUC4","videoTitle":"Week 9 · Video walkthrough","why":"Unpivot turns repeated month columns into month/value pairs suitable for reporting over time.","workthrough":"Create a small wide monthly table from learning_monthly_kpis.csv, then unpivot Jan–Mar measures into records.","evidence":"Explain which columns remain identifiers and what new field becomes the measure name.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerquery-week-09.md"},{"week":10,"dataset":"learning_sales_quality_lab.csv","datasetLabel":"Learning Sales Quality Lab (CSV)","video":"https://www.youtube.com/watch?v=VO-MyVMKUC4","videoTitle":"Week 10 · Video walkthrough","why":"M uses let/in expressions and typed values; named steps should describe reproducible transformations.","workthrough":"Open Advanced Editor and trace Source → Changed Type → Cleaned Region → Grouped Rows with friendly names.","evidence":"Refresh safely and supply a short step-by-step data-preparation handover.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/powerquery-week-10.md"}],"statistics":[{"week":1,"dataset":"learning_statistics_sample.csv","datasetLabel":"Learning Statistics Sample (CSV)","video":"https://www.youtube.com/watch?v=bvglAgAZtXE","videoTitle":"Week 1 · Video walkthrough","why":"Population is everyone covered by a decision; a sample is a subset. The unit of analysis must remain consistent.","workthrough":"Use the delivery observations to identify variable types and the population you hope to describe.","evidence":"Explain why 100 observations do not necessarily represent every order in another region.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/statistics-week-01.md"},{"week":2,"dataset":"learning_statistics_sample.csv","datasetLabel":"Learning Statistics Sample (CSV)","video":"https://www.youtube.com/watch?v=SzZ6GpcfoQY","videoTitle":"Week 2 · Video walkthrough","why":"Mean uses all numeric values; median is resistant to extreme observations, and mode identifies the most common value.","workthrough":"Compute mean and median delivery_minutes. Investigate the extreme 220-minute row.","evidence":"State which summary better describes a typical delivery and why.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/statistics-week-02.md"},{"week":3,"dataset":"learning_statistics_sample.csv","datasetLabel":"Learning Statistics Sample (CSV)","video":"https://www.youtube.com/watch?v=SzZ6GpcfoQY","videoTitle":"Week 3 · Video walkthrough","why":"Standard deviation measures spread around the mean in the original units and is sensitive to outliers.","workthrough":"Compute sample variance and standard deviation with and without the extreme observation.","evidence":"Describe the units and why reporting only the average would hide instability.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/statistics-week-03.md"},{"week":4,"dataset":"learning_statistics_sample.csv","datasetLabel":"Learning Statistics Sample (CSV)","video":"https://www.youtube.com/watch?v=SzZ6GpcfoQY","videoTitle":"Week 4 · Video walkthrough","why":"Histograms group continuous measurements into bins; too-wide and too-narrow bins can obscure structure.","workthrough":"Create a delivery-time frequency table with clear bin boundaries and inspect skew and outliers.","evidence":"Compare the histogram to a bar chart of regions and explain the variable-type distinction.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/statistics-week-04.md"},{"week":5,"dataset":"learning_experiment.csv","datasetLabel":"Learning Experiment (CSV)","video":"https://www.youtube.com/watch?v=bvglAgAZtXE","videoTitle":"Week 5 · Video walkthrough","why":"A large non-random sample is still biased. Sampling method affects whether findings generalise.","workthrough":"Inspect experiment records by device and region; compare group composition before measuring lift.","evidence":"Identify who might be missing from the sample and what additional data would reduce bias.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/statistics-week-05.md"},{"week":6,"dataset":"learning_experiment.csv","datasetLabel":"Learning Experiment (CSV)","video":"https://www.youtube.com/watch?v=_IgyaD7vOOA","videoTitle":"Week 6 · Video walkthrough","why":"Conditional probability changes the denominator to the group in the condition.","workthrough":"Calculate conversion proportion within mobile sessions and overall; list numerators and denominators.","evidence":"Explain the difference between P(Convert | Mobile) and P(Mobile and Convert).","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/statistics-week-06.md"},{"week":7,"dataset":"learning_statistics_sample.csv","datasetLabel":"Learning Statistics Sample (CSV)","video":"https://www.youtube.com/watch?v=xZ_z8KWkhXE","videoTitle":"Week 7 · Video walkthrough","why":"A positive correlation does not prove that one metric causes the other; a third factor may affect both.","workthrough":"Scatterplot delivery minutes and satisfaction; examine the outlier and alternative operational explanations.","evidence":"Write one association statement and two reasons a causal conclusion would be premature.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/statistics-week-07.md"},{"week":8,"dataset":"learning_experiment.csv","datasetLabel":"Learning Experiment (CSV)","video":"https://www.youtube.com/watch?v=bS2Tmxpc0mw","videoTitle":"Week 8 · Video walkthrough","why":"A confidence interval describes uncertainty for a method under assumptions; bias is not corrected by a narrow interval.","workthrough":"Estimate A/B conversion rates from learning_experiment.csv and compare plausible uncertainty intervals.","evidence":"Report sample sizes and discuss why a small difference may be inconclusive.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/statistics-week-08.md"},{"week":9,"dataset":"learning_experiment.csv","datasetLabel":"Learning Experiment (CSV)","video":"https://www.youtube.com/watch?v=vyX4m89VkyI","videoTitle":"Week 9 · Video walkthrough","why":"A p-value measures compatibility with a null model and is not the probability that the null hypothesis is true.","workthrough":"Define a null of equal A/B conversion, set alpha before inspection and calculate or interpret a suitable test.","evidence":"Report effect size, interval and caveats, not just a pass/fail significance label.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/statistics-week-09.md"},{"week":10,"dataset":"learning_forecast_series.csv","datasetLabel":"Learning Forecast Series (CSV)","video":"https://www.youtube.com/watch?v=7ArmBVF2dCs","videoTitle":"Week 10 · Video walkthrough","why":"A regression line is a fitted association and should be validated on unseen or held-out observations.","workthrough":"Plot month and net_sales_ngn, fit a simple baseline and inspect residual seasonality.","evidence":"Separate interpolation from extrapolation and state what accuracy measure you would track.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/statistics-week-10.md"}],"python":[{"week":1,"dataset":"mastery_orders.csv","datasetLabel":"Mastery Orders (CSV)","video":"https://www.youtube.com/watch?v=GPVsHOlRBBI&t=324s","videoTitle":"Week 1 · Video walkthrough","why":"The REPL, notebook and script are different execution interfaces. A reproducible analysis starts with known inputs and a working directory.","workthrough":"Read mastery_orders.csv using pandas, print head(), dtypes and shape, and verify the source path.","evidence":"Record package versions and avoid assuming a notebook cell ran simply because it is visible.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/python-week-01.md"},{"week":2,"dataset":"mastery_orders.csv","datasetLabel":"Mastery Orders (CSV)","video":"https://www.youtube.com/watch?v=GPVsHOlRBBI&t=4166s","videoTitle":"Week 2 · Video walkthrough","why":"Variables reference values; conditions should be explicit and tests should cover all branches.","workthrough":"Use order status to classify rows with if/elif/else and compute one completed line total.","evidence":"Check both a completed and a cancelled record and explain the output.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/python-week-02.md"},{"week":3,"dataset":"mastery_orders.csv","datasetLabel":"Mastery Orders (CSV)","video":"https://www.youtube.com/watch?v=GPVsHOlRBBI&t=5802s","videoTitle":"Week 3 · Video walkthrough","why":"Functions reduce duplicated logic, but reusable functions need clear contracts for input types and missing values.","workthrough":"Define line_revenue(quantity,unit_price) and test positive, zero and missing inputs.","evidence":"Document parameters, units and expected exceptions before using the function in pandas.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/python-week-03.md"},{"week":4,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=GPVsHOlRBBI&t=14578s","videoTitle":"Week 4 · Video walkthrough","why":"A pandas DataFrame has row/column labels, and selection changes the population before aggregation.","workthrough":"Filter learning_sales_2026.csv to completed North-region orders with boolean masks.","evidence":"Compare filtered row count and summed revenue to an independent calculation.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/python-week-04.md"},{"week":5,"dataset":"learning_sales_quality_lab.csv","datasetLabel":"Learning Sales Quality Lab (CSV)","video":"https://www.youtube.com/watch?v=GPVsHOlRBBI&t=29035s","videoTitle":"Week 5 · Video walkthrough","why":"astype, to_datetime, merge and drop_duplicates all need declared assumptions; silent type coercion can lose information.","workthrough":"Read the intentionally dirty CSV, inspect errors and add an exceptions DataFrame before correcting values.","evidence":"Compare pre/post row counts, and explain how duplicated keys can inflate joined totals.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/python-week-05.md"},{"week":6,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=GPVsHOlRBBI&t=18045s","videoTitle":"Week 6 · Video walkthrough","why":"Groupby and pivot_table produce different report shapes; always verify the metric unit and aggregation.","workthrough":"Use monthly KPIs to build a region × month summary and compute target attainment from aggregated totals.","evidence":"Reconcile monthly totals and export a presentation-ready CSV.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/python-week-06.md"},{"week":7,"dataset":"learning_statistics_sample.csv","datasetLabel":"Learning Statistics Sample (CSV)","video":"https://www.youtube.com/watch?v=GPVsHOlRBBI&t=28456s","videoTitle":"Week 7 · Video walkthrough","why":"A confidence interval, model coefficient or correlation must be paired with its assumptions.","workthrough":"Use the statistics sample to describe outliers and plot delivery time versus satisfaction.","evidence":"Distinguish exploratory association from evidence that changing delivery time causes satisfaction.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/python-week-07.md"},{"week":8,"dataset":"learning_statistics_sample.csv","datasetLabel":"Learning Statistics Sample (CSV)","video":"https://www.youtube.com/watch?v=GPVsHOlRBBI&t=8240s","videoTitle":"Week 8 · Video walkthrough","why":"NumPy vector operations are elementwise unless matrix multiplication is explicitly requested.","workthrough":"Convert price and quantity columns to NumPy arrays and compute line totals vectorially.","evidence":"Check output dimensions, broadcasting behavior and a hand-calculated row.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/python-week-08.md"},{"week":9,"dataset":"learning_forecast_series.csv","datasetLabel":"Learning Forecast Series (CSV)","video":"https://www.youtube.com/watch?v=GPVsHOlRBBI&t=21168s","videoTitle":"Week 9 · Video walkthrough","why":"Time-series analysis must respect time order; random train/test splits can leak future information.","workthrough":"Make a 3-month trailing baseline from the forecast series, then test it on later months.","evidence":"Report MAE and compare against a naive last-month forecast.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/python-week-09.md"},{"week":10,"dataset":"mastery_orders.csv","datasetLabel":"Mastery Orders (CSV)","video":"https://www.youtube.com/watch?v=GPVsHOlRBBI&t=28196s","videoTitle":"Week 10 · Video walkthrough","why":"A repeatable analysis can be re-run from source, producing matching outputs after controlled changes.","workthrough":"Package source loading, cleaning, validation, aggregation, charting and a written decision memo into functions.","evidence":"Describe dependencies and tests, then reconcile output totals to raw records.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/python-week-10.md"}],"ai":[{"week":1,"dataset":"learning_ai_review_cases.csv","datasetLabel":"Learning Ai Review Cases (CSV)","video":"https://www.youtube.com/watch?v=DLpz6V_4SpA","videoTitle":"Week 1 · Video walkthrough","why":"Generative AI predicts plausible output and should be treated as an assistant, not an authority on dataset truth.","workthrough":"Review prompt-risk cases and sort them into useful assistance, unsupported assumption and privacy concern.","evidence":"State what a human analyst must verify before publishing an AI-generated insight.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/ai-week-01.md"},{"week":2,"dataset":"learning_ai_review_cases.csv","datasetLabel":"Learning Ai Review Cases (CSV)","video":"https://www.youtube.com/watch?v=A-duulqglqpbk&t=1110s","videoTitle":"Week 2 · Video walkthrough","why":"A strong analytical prompt defines objective, table schema, business rules, constraints and expected result format.","workthrough":"Turn the vague “Summarise sales” prompt into one with time boundaries, net revenue definition and a reconciliation requirement.","evidence":"Compare the two prompts and identify three ambiguities you removed.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/ai-week-02.md"},{"week":3,"dataset":"learning_ai_review_cases.csv","datasetLabel":"Learning Ai Review Cases (CSV)","video":"https://www.youtube.com/watch?v=TImRJTzphhE","videoTitle":"Week 3 · Video walkthrough","why":"Removing obvious names is not sufficient privacy protection; identifiers and combinations of fields can re-identify people.","workthrough":"Use the synthetic AI cases to produce a checklist of approval, minimisation and access restrictions.","evidence":"Rewrite an unsafe employee-data prompt into a permitted aggregate-only request.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/ai-week-03.md"},{"week":4,"dataset":"learning_sales_quality_lab.csv","datasetLabel":"Learning Sales Quality Lab (CSV)","video":"https://www.youtube.com/watch?v=DLpz6V_4SpA&t=205s","videoTitle":"Week 4 · Video walkthrough","why":"AI can suggest formulas or transformation steps but may invent fields and change business meaning.","workthrough":"Provide the dirty sales CSV schema and request a Power Query cleanup plan; review each suggested transformation.","evidence":"Reject any suggestion that deletes exceptional records without documenting why.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/ai-week-04.md"},{"week":5,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=DLpz6V_4SpA&t=347s","videoTitle":"Week 5 · Video walkthrough","why":"Generated SQL must be reviewed for schema correctness, row grain, filters and read-only scope.","workthrough":"Ask AI for a regional sales query for the supplied SQLite schema and test its output against a manual total.","evidence":"Identify hallucinated columns, missing joins or ambiguous denominator definitions.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/ai-week-05.md"},{"week":6,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=DLpz6V_4SpA&t=488s","videoTitle":"Week 6 · Video walkthrough","why":"AI-generated Python code can be useful for cleaning and EDA, but running it still requires validation.","workthrough":"Request a pandas groupby example for the sales file and review its assumptions before execution.","evidence":"Show one assertion that would catch an unexpected duplicate or missing amount.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/ai-week-06.md"},{"week":7,"dataset":"learning_monthly_kpis.csv","datasetLabel":"Learning Monthly Kpis (CSV)","video":"https://www.youtube.com/watch?v=DLpz6V_4SpA&t=743s","videoTitle":"Week 7 · Video walkthrough","why":"A report narrative should be grounded in calculated measures, with clear evidence and uncertainty.","workthrough":"Supply verified KPI values to AI, ask for a 100-word executive summary, then audit every numeric claim.","evidence":"Present a final human-edited paragraph with sources, caveats and recommended action.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/ai-week-07.md"},{"week":8,"dataset":"learning_experiment.csv","datasetLabel":"Learning Experiment (CSV)","video":"https://www.youtube.com/watch?v=pkYkeIdhlT0","videoTitle":"Week 8 · Video walkthrough","why":"Forecasts and ML claims must distinguish prediction from causal explanations and avoid leakage.","workthrough":"Give AI a time-series baseline task with training cutoff and evaluation metric, then critique its plan.","evidence":"Explain why random shuffling would be inappropriate for a forward-looking forecast.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/ai-week-08.md"},{"week":9,"dataset":"learning_ai_review_cases.csv","datasetLabel":"Learning Ai Review Cases (CSV)","video":"https://www.youtube.com/watch?v=pkYkeIdhlT0","videoTitle":"Week 9 · Video walkthrough","why":"Automated agents can execute tools, so permissions, checkpoints, rollback and audit trails matter.","workthrough":"Design a read-only analysis automation that drafts a report but requires approval before distribution.","evidence":"List safeguards, failure notifications and a manual override.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/ai-week-09.md"},{"week":10,"dataset":"learning_sales_2026.csv","datasetLabel":"Learning Sales 2026 (CSV)","video":"https://www.youtube.com/watch?v=DLpz6V_4SpA","videoTitle":"Week 10 · Video walkthrough","why":"An AI-assisted analysis is only complete when human accountability and reproducible checks are documented.","workthrough":"Combine synthetic sales data, schema documentation, validation log and a final presentation narrative.","evidence":"Submit a one-page AI-use statement naming verified calculations, limitations and responsible reviewer.","guide":"WEEKLY_PRACTICE_DATA_GUIDE.md","worksheet":"weekly/ai-week-10.md"}]};
